314	const DEFINITION_POS_HEADER = String.raw`(?:^|[\n;]|\|\|)\s*(?:\d+\s*[.)》]\s*)?(?:[–—-]\s*)?`;
315	const DEFINITION_POS_MARKERS: Array<[RegExp, string]> = [
316	  [new RegExp(`${DEFINITION_POS_HEADER}(?:іменник|noun)(?=$|[\\s,;:])`, "imu"), "іменник"],
317	  [new RegExp(`${DEFINITION_POS_HEADER}(?:дієслово|verb)(?=$|[\\s,;:])`, "imu"), "дієслово"],
318	  [new RegExp(`${DEFINITION_POS_HEADER}(?:прикметник|adjective)(?=$|[\\s,;:])`, "imu"), "прикметник"],
319	  [new RegExp(`${DEFINITION_POS_HEADER}(?:прислівник|присл\\.|adverb)(?=$|[\\s,;:])`, "imu"), "прислівник"],
320	  [new RegExp(`${DEFINITION_POS_HEADER}(?:числівник|numeral)(?=$|[\\s,;:])`, "imu"), "числівник"],
321	  [new RegExp(`${DEFINITION_POS_HEADER}(?:прийменник|приймен\\.|preposition)(?=$|[\\s,;:])`, "imu"), "прийменник"],
322	  [new RegExp(`${DEFINITION_POS_HEADER}(?:сполучник|спол\\.|conjunction)(?=$|[\\s,;:])`, "imu"), "сполучник"],
323	  [new RegExp(`${DEFINITION_POS_HEADER}(?:частка|particle)(?=$|[\\s,;:])`, "imu"), "частка"],
324	];
