326	function normalizePosLabels(value: string | null | undefined) {
327	  const text = value?.trim();
328	  if (!text) return [];
329	  return text
330	    .split(/\s*(?:[,;/|+]|\b(?:or|або|і|та)\b)\s*/iu)
331	    .map((part) => part.trim())
332	    .filter(Boolean)
333	    .map((part) => {
334	      const key = part.toLocaleLowerCase("uk");
335	      const alias = Object.keys(POS_LABELS).find(
336	        (candidate) =>
337	          key === candidate ||
338	          key.startsWith(`${candidate}:`) ||
339	          key.startsWith(`${candidate}.`) ||
340	          key.startsWith(`${candidate} `),
341	      );
342	      return alias ? { label: POS_LABELS[alias]!, known: true } : { label: part, known: false };
343	    });
344	}
345	
346	function definitionCardPosLabels(cards: DefinitionCard[] | undefined) {
347	  const labels: string[] = [];
348	  for (const card of cards ?? []) {
349	    for (const definition of card.definitions ?? []) {
350	      for (const [pattern, label] of DEFINITION_POS_MARKERS) {
351	        if (pattern.test(definition) && !labels.includes(label)) labels.push(label);
352	      }
353	    }
354	  }
355	  return labels;
356	}
