358	export function formatPos(
359	  pos: string | null | undefined,
360	  morphologyPos: string | null | undefined,
361	  signals: {
362	    cefrPos?: string | null;
363	    translationPos?: string | null;
364	    definitionCards?: DefinitionCard[];
365	  } = {},
366	) {
367	  const labels: string[] = [];
368	  const fallbackLabels: string[] = [];
369	  const addSignal = (value: string | null | undefined) => {
370	    for (const normalized of normalizePosLabels(value)) {
371	      const target = normalized.known ? labels : fallbackLabels;
372	      if (!target.includes(normalized.label)) target.push(normalized.label);
373	    }
374	  };
375	
376	  // Preserve the learner-facing precedence: VESUM morphology first, article
377	  // metadata second, then the remaining enrichment signals.
378	  addSignal(morphologyPos);
379	  addSignal(pos);
380	  addSignal(signals.cefrPos);
381	  addSignal(signals.translationPos);
382	  for (const label of definitionCardPosLabels(signals.definitionCards)) addSignal(label);
383	
384	  return (labels.length > 0 ? labels : fallbackLabels).join(" · ") || null;
385	}
