844	function buildSourceList(args: {
845	  entry: LexiconEntryView;
846	  enrichment: Enrichment | null;
847	  definitionCards: DefinitionCard[];
848	  sections: LexiconSections | null;
849	}) {
850	  const { entry, enrichment, definitionCards, sections } = args;
851	  const sources = new Set<string>();
852	  for (const source of enrichment?.sources ?? []) sources.add(source);
853	  if (entry.pronunciation?.source) sources.add(entry.pronunciation.source);
854	  if (enrichment?.stress?.source) sources.add(enrichment.stress.source);
855	  if (enrichment?.cefr?.source) sources.add(enrichment.cefr.source);
856	  if (enrichment?.morphology?.source) sources.add(enrichment.morphology.source);
857	  if (enrichment?.meaning?.source) sources.add(enrichment.meaning.source);
858	  for (const card of definitionCards) sources.add(card.source);
859	  if (enrichment?.etymology?.source) sources.add(enrichment.etymology.source);
860	  if (sections?.synonyms?.source) sources.add(sections.synonyms.source);
861	  if (sections?.antonyms?.source) sources.add(sections.antonyms.source);
862	  if (sections?.homonyms?.source) sources.add(sections.homonyms.source);
863	  if (sections?.paronyms?.source) sources.add(sections.paronyms.source);
864	  if (sections?.idioms?.source) sources.add(sections.idioms.source);
865	  if (enrichment?.literary_attestation?.source) sources.add(enrichment.literary_attestation.source);
866	  if (enrichment?.translation?.source) sources.add(enrichment.translation.source);
867	  if (entry.course_usage.length > 0) sources.add("curriculum_vocabulary");
868	  if (entry.wiki_reference?.wikipedia) sources.add("query_wikipedia");
869	  if (entry.wiki_reference?.wiktionary_url) sources.add("uk.wiktionary");
870	  return Array.from(sources).sort((a, b) => a.localeCompare(b, "uk"));
871	}

