2	/**
3	 * Dynamic route for ESUM etymology entries.
4	 *
5	 * `getStaticPaths` reads the build-time manifest at
6	 * `src/data/etymology-manifest.json` and emits one Astro page per slug when
7	 * `BUILD_ETYMOLOGY_ROUTES=1` is set. Normal lesson preview/build loops skip
8	 * these routes so editing one module does not rebuild the ESUM reference site.
9	 * Three URL patterns are produced:
10	 *
11	 *   /etymology/<slug>/           — single-entry page (24,765 - 2,142 paths)
12	 *   /etymology/<slug>/           — polysemy landing for slugs with >1 entry (2,142 paths)
13	 *   /etymology/<slug>-<vol>-<page>(-N)?/   — individual disambig entry under a polysemy slug
14	 *
15	 * Wraps content in the custom course shell.
16	 */
17	import CourseLayout from '../../layouts/CourseLayout.astro';
18	import manifest from '../../data/etymology-manifest.json';
19	
20	interface EtymEntry {
21	  id: number;
22	  lemma: string;
23	  vol: number;
24	  page: number;
25	  slug: string;
26	  page_slug: string;
27	  etymology_text: string;
28	  cognate_forms: Record<string, string>;
29	  cognate_forms_recovered?: Record<string, string>;
30	  proto_form: string | null;
31	}
32	
33	interface Manifest {
34	  version: string;
35	  generated_at: string;
36	  stats: Record<string, number>;
37	  entries: EtymEntry[];
38	  slug_groups: Record<string, string[]>;
39	}
40	
41	const MARKER_LABELS: Record<string, string> = {
42	  'ав.': 'Авестійська',
43	  'болг.': 'Болгарська',
44	  'бр.': 'Білоруська',
45	  'гот.': 'Готська',
46	  'гр.': 'Грецька',
47	  'дінд.': 'Давньоіндійська',
48	  'др.': 'Давньоруська',
49	  'іє.': 'Індоєвропейська',
50	  'лат.': 'Латинська',
51	  'лит.': 'Литовська',
52	  'п.': 'Польська',
53	  'псл.': "Праслов'янська",
54	  'р.': 'Російська',
55	  'слн.': 'Словенська',
56	  'слц.': 'Словацька',
57	  'стел.': "Старослов'янська",
58	  'схв.': 'Сербохорватська',
59	  'ч.': 'Чеська',
60	};
61	
62	type EntryProps = {
63	  kind: 'entry';
64	  entry: EtymEntry;
65	};
66	type LandingProps = {
67	  kind: 'landing';
68	  slug: string;
69	  entries: EtymEntry[];
70	};
71	type RouteProps = EntryProps | LandingProps;
72	
73	export async function getStaticPaths() {
74	  const buildEtymologyRoutes = ['1', 'true', 'yes'].includes(
75	    (process.env.BUILD_ETYMOLOGY_ROUTES ?? '').toLowerCase(),
76	  );
77	
78	  const data = manifest as Manifest;
79	  const byPageSlug = new Map<string, EtymEntry>();
80	  for (const e of data.entries) byPageSlug.set(e.page_slug, e);
81	
82	  const paths: Array<{ params: { slug: string }; props: RouteProps }> = [];
83	  const seen = new Set<string>();
84	  const addPath = (slug: string, props: RouteProps) => {
85	    if (seen.has(slug)) return;
86	    seen.add(slug);
87	    paths.push({ params: { slug }, props });
88	  };
89	  const addSlugGroup = (slug: string, page_slugs: string[]) => {
90	    if (page_slugs.length === 1) {
91	      const entry = byPageSlug.get(page_slugs[0]);
92	      if (entry) addPath(slug, { kind: 'entry', entry });
93	    } else {
94	      const entries = page_slugs.map((ps) => byPageSlug.get(ps)).filter(Boolean) as EtymEntry[];
95	      if (entries.length === 0) return;
96	      addPath(slug, { kind: 'landing', slug, entries });
97	      for (const entry of entries) addPath(entry.page_slug, { kind: 'entry', entry });
98	    }
99	  };
100	
101	  if (!buildEtymologyRoutes) {
102	    console.warn(
103	      '[etymology] Skipping full ESUM dynamic routes. Set BUILD_ETYMOLOGY_ROUTES=1 for the full reference build.',
104	    );
105	    const featuredSlugs = new Set(['dim', 'zhinka', 'khlib', 'voda']);
106	    for (const [slug, page_slugs] of Object.entries(data.slug_groups)) {
107	      if (featuredSlugs.has(slug)) addSlugGroup(slug, page_slugs);
108	    }
109	    return paths;
110	  }
111	
112	  for (const [slug, page_slugs] of Object.entries(data.slug_groups)) {
113	    addSlugGroup(slug, page_slugs);
114	  }
115	
116	  return paths;
117	}
118	
119	const props = Astro.props as RouteProps;
120	
121	const ARCHIVE_URL =
122	  'https://archive.org/search?query=Етимологічний%20словник%20української%20мови';
123	
124	// Build the page frontmatter + content body based on the route kind.
125	function entryFrontmatter(entry: EtymEntry) {
126	  return {
127	    title: entry.lemma,
128	    description: `Етимологія слова «${entry.lemma}» — ЕСУМ, том ${entry.vol}, с. ${entry.page}`,
129	    template: 'doc' as const,
130	    pagefind: true,
131	  };
132	}
133	
134	function landingFrontmatter(entries: EtymEntry[]) {
135	  const lemmas = Array.from(new Set(entries.map((e) => e.lemma))).slice(0, 3).join(' / ');
136	  return {
137	    title: lemmas,
138	    description: `Етимологія слова «${lemmas}» — кілька статей в ЕСУМ`,
139	    template: 'doc' as const,
140	    pagefind: true,
141	  };
142	}
143	
144	const pageMeta = props.kind === 'entry'
145	  ? entryFrontmatter(props.entry)
146	  : landingFrontmatter(props.entries);
147	
148	const summary = (text: string, length = 90): string => {
149	  const collapsed = text.replace(/\s+/g, ' ').trim();
150	  return collapsed.length > length ? collapsed.slice(0, length) + '…' : collapsed;
151	};
152	
153	// HTML-escape a raw text fragment before injecting into set:html output.
154	const escapeHtml = (s: string): string =>
155	  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
156	
157	// Known ESUM language abbreviation markers. Used by the inline-marker
158	// renderer to italicize the abbreviation and (when known) attach the
159	// full language name as a tooltip.
160	const LANG_ABBR_LOOKUP: Record<string, string> = MARKER_LABELS;
161	
162	// Source-citation tokens that follow an ESUM entry. ESUM uses these to cite
163	// where a derivative or meaning was attested. Rendering them as small muted
164	// chips helps the reader visually separate citation noise from etymology
165	// content.
166	const CITATION_TOKENS = new Set([
167	  'Ж', 'Я', 'О', 'Г', 'Нед', 'Бі', 'Куз', 'Мак', 'Шейк', 'Чаб', 'ВеЗа',
168	  'ВеУг', 'Гр', 'Дз', 'Дз.', 'Ме', 'Пі', 'ЛексПолі', 'ЕЗб', 'ССУМ',
169	  'СУМ', 'СІС', 'СІС?', 'ЗСРЯ', 'ЕСЯ', 'ЕСлС', 'РУДБЕ', 'Преобр',
170	  'Фасмер', 'Шанский', 'Брандт', 'МасНпек', 'Маспек', 'Маsпеk',
171	  'Львов', 'Преобр.', 'Фасмер.', 'Брюкнер', 'BгйcКпег', 'Vasmer',
172	]);
173	
174	/**
175	 * Render the ESUM etymology body as readable HTML.
176	 *
177	 * The raw `etymology_text` is a dense single paragraph stuffed with
178	 *
179	 *   - bracketed dialectal/archaic forms     [віднйха]
180	 *   - quoted meanings (Ukrainian gloss)     «діжечка для води»
181	 *   - language abbreviations                р., бр., п., ч., псл.
182	 *   - source-citation markers               Ж, Я, Нед, СУМ, Фасмер
183	 *   - section separators                    `--` or `—`
184	 *
185	 * The legacy renderer dumped the whole blob into a `<div>` with
186	 * `white-space: pre-wrap`, which left dictionary readers with an
187	 * unreadable wall of text.
188	 *
189	 * This renderer:
190	 *   1. Splits on `--` / `—` boundaries that ESUM uses to separate the
191	 *      derivatives list, cognates section, and citation block.
192	 *   2. Wraps bracketed forms, quoted meanings, language markers, and
193	 *      citation tokens in span classes that the stylesheet typesets
194	 *      with distinct weight/color/size.
195	 *   3. Falls back to plain text for fragments that don't match any
196	 *      pattern (so unknown content never disappears).
197	 */
198	function renderEtymologyBody(rawText: string): string {
199	  if (!rawText) return '';
200	
201	  // Normalize whitespace; the source has hard line breaks from PDF text
202	  // layer extraction that we want to collapse into prose.
203	  const collapsed = rawText.replace(/\s+/g, ' ').trim();
204	
205	  // Split on `--` or `—` boundaries to recover ESUM's section structure.
206	  // Each segment becomes one rendered paragraph.
207	  const segments = collapsed.split(/\s+(?:--|—)\s+/).filter((s) => s.trim().length > 0);
208	
209	  const renderSegment = (segment: string): string => {
210	    // Tokenize: walk the string, recognizing brackets, quotes, lang markers,
211	    // citation tokens, and plain text. Order matters: brackets first because
212	    // they enclose other content; then quotes; then markers; then citations.
213	    let out = '';
214	    let i = 0;
215	    while (i < segment.length) {
216	      const ch = segment[i];
217	
218	      // Bracketed form: [...] -- dialectal/archaic marker in ESUM.
219	      // We only close on the actual `]`. Using `)` as a permissive fallback
220	      // captured too much (e.g. swallowed `(ент.)` parentheticals that ESUM
221	      // writes inside its derivative lists). When the close `]` is OCR-damaged
222	      // and missing, fall through to plain text instead of spanning aggressively.
223	      if (ch === '[') {
224	        const closeIdx = segment.indexOf(']', i);
225	        const closeBracketIdx = segment.indexOf('[', i + 1);
226	        let end = -1;
227	        const candidates = [closeIdx, closeBracketIdx].filter((x) => x > i);
228	        if (candidates.length > 0) {
229	          end = Math.min(...candidates);
230	        }
231	        if (end > i && end - i < 80) {
232	          const inner = segment.slice(i + 1, end);
233	          out += `<span class="esum-bracket">[${escapeHtml(inner)}]</span>`;
234	          i = end + 1;
235	          continue;
236	        }
237	      }
238	
239	      // Quoted gloss: «...»
240	      if (ch === '«') {
241	        const end = segment.indexOf('»', i);
242	        if (end > i && end - i < 200) {
243	          const inner = segment.slice(i + 1, end);
244	          out += `<span class="esum-gloss">«${escapeHtml(inner)}»</span>`;
245	          i = end + 1;
246	          continue;
247	        }
248	      }
249	
250	      // Language abbreviation: Cyrillic 1-5 chars ending in `.`, after a
251	      // space or at the start of a segment.
252	      if (/[а-яґіїєА-ЯҐІЇЄ]/.test(ch) && (i === 0 || /[\s,;]/.test(segment[i - 1]))) {
253	        const m = segment.slice(i).match(/^[а-яґіїєА-ЯҐІЇЄ]{1,5}\.(?=\s)/);
254	        if (m) {
255	          const abbr = m[0];
256	          if (LANG_ABBR_LOOKUP[abbr]) {
257	            const fullName = LANG_ABBR_LOOKUP[abbr];
258	            out += `<span class="esum-lang" title="${escapeHtml(fullName)}">${escapeHtml(abbr)}</span>`;
259	            i += abbr.length;
260	            continue;
261	          }
262	        }
263	      }
264	
265	      // Citation token: standalone capital word(s) from CITATION_TOKENS.
266	      if (/[А-ЯҐІЇЄ]/.test(ch) && (i === 0 || /\s/.test(segment[i - 1]))) {
267	        const m = segment.slice(i).match(/^[А-ЯҐІЇЄ][а-яґіїєА-ЯҐІЇЄ.?]{0,8}/);
268	        if (m && CITATION_TOKENS.has(m[0])) {
269	          out += `<span class="esum-cite">${escapeHtml(m[0])}</span>`;
270	          i += m[0].length;
271	          continue;
272	        }
273	      }
274	
275	      // Plain text fallback: consume exactly one char and re-check on next
276	      // iteration. (Greedy consumption to the next bracket/quote would skip
277	      // language markers and citation tokens that the per-position checks
278	      // above can only match when sitting on the starting char.)
279	      out += escapeHtml(ch);
280	      i += 1;
281	    }
282	    return out;
283	  };
284	
285	  return segments
286	    .map((seg, idx) => {
287	      const rendered = renderSegment(seg);
288	      const isFirst = idx === 0;
289	      return `<p class="esum-body-seg${isFirst ? ' esum-body-derivatives' : ''}">${rendered}</p>`;
290	    })
291	    .join('\n');
292	}
