39	export function dateSeed(d: Date): number {
40	  return d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate();
41	}
42	
43	export function pickDaily<T>(pool: T[], seed: number, n: number): T[] {
44	  const result = [...pool];
45	  const rand = seededRandom(seed);
46	  for (let i = result.length - 1; i > 0; i--) {
47	    const j = Math.floor(rand() * (i + 1));
48	    [result[i], result[j]] = [result[j], result[i]];
49	  }
50	  return result.slice(0, Math.max(0, Math.min(n, result.length)));
51	}
