53	/**
54	 * Deterministic numeric contribution for a deck id, for combining with `dateSeed`
55	 * (D10: `pickDaily(deckPool, dateSeed(today) + deckId, 12)`). `deckId` is a string,
56	 * so a literal `+` would coerce the whole expression to NaN/0 — this hash gives the
57	 * formula's intent (date AND deck both drive the draw) a real numeric seed.
58	 */
59	export function deckSeed(deckId: string): number {
60	  let hash = 2166136261;
61	  for (let index = 0; index < deckId.length; index += 1) {
62	    hash ^= deckId.charCodeAt(index);
63	    hash = Math.imul(hash, 16777619);
64	  }
65	  return hash >>> 0;
66	}
67	
68	/**
69	 * #6132: deterministic contribution for an explicit re-roll (the learner asking to
70	 * see a different pick set without waiting for the calendar day to change).
71	 * Combines additively with `dateSeed`/`deckSeed` the same way they combine with each
72	 * other. `count` is 0 for the day's default draw and increments once per re-roll tap;
73	 * multiplying by a large prime keeps consecutive counts from producing near-identical
74	 * permutations under `pickDaily`'s mulberry32-style generator.
75	 */
76	export function reRollSeed(count: number): number {
77	  return (count * 104729) >>> 0;
78	}

