1	import type { EntryRecord } from "@site/src/lib/lexicon/atlas-data-source";
2	import type { LexiconEntry } from "@site/src/lib/lexicon/atlasDb";
3	import { normalize as normalizeAtlasSearchText } from "@site/src/lib/lexicon/search";
4	import type { PracticeLevel } from "@site/src/lib/lexicon/runtime-contract";
5	
6	const MORPHOLOGY_SUPPRESSED = new Set([
7	  "multiword_term",
8	  "expression",
9	  "phraseologism",
10	  "proverb",
11	]);
12	
13	/** Build an EntryRecord for unit tests that previously passed bare LexiconEntry props. */
14	export function entryRecordFromParts(
15	  entry: LexiconEntry,
16	  options?: {
17	    componentLinkTargets?: Map<string, string>;
18	    lemmaEntries?: LexiconEntry[];
19	    practiceLevels?: PracticeLevel[];
20	  },
21	): EntryRecord {
22	  const targets = options?.componentLinkTargets ?? new Map<string, string>();
23	  const lemmaSlugs = new Set(
24	    (options?.lemmaEntries ?? [])
25	      .filter((item) => item.entry_type === "lemma")
26	      .map((item) => item.url_slug),
27	  );
28	  const componentLinks = MORPHOLOGY_SUPPRESSED.has(entry.entry_type ?? "")
29	    ? (entry.lemma.match(/[\p{L}\p{M}]+(?:['’][\p{L}\p{M}]+)*/gu) ?? []).map((text) => {
30	        const targetSlug = targets.get(normalizeAtlasSearchText(text)) ?? null;
31	        if (targetSlug && lemmaSlugs.has(targetSlug) && targetSlug !== entry.url_slug) {
32	          return { text, targetSlug };
33	        }
34	        return { text, targetSlug: null };
35	      })
36	    : [];
37	
38	  return {
39	    slug: entry.url_slug,
40	    kind: entry.entry_type == null ? "form_route" : "article",
41	    entry,
42	    aliases: [],
43	    relations: [],
44	    provenance: [],
45	    renderContext: {
46	      componentLinks,
47	      practiceLevels: options?.practiceLevels ?? [],
48	    },
49	  };
50	}
51	
52	export function articleProps(
