13	const KAIKKI_SOURCE = "kaikki/Wiktionary (CC BY-SA 3.0)";
14	const MAX_LENGTH = 160;
15	
16	// Matches a parenthetical that contains Latin-script characters.
17	// Tolerates one level of nested parentheses, which Wiktionary uses for
18	// transliterations: (naštovx(núty)).
19	const LATIN_PARENTHETICAL_RE =
20	  /\((?:[^()]|\([^()]*\))*[A-Za-z](?:[^()]|\([^()]*\))*\)/g;
21	
22	// Imperial-comparison clauses that Kaikki sometimes appends.
23	const COMPARE_CLAUSE_RE = /\s*[,.]?\s*\b[Cc]ompare\s+[A-Z][a-z]+\b[^.]*\.?/g;
24	
25	// Borrowed-looking license/source fragments that should never be prose.
26	const SOURCE_FRAGMENT_RE = /\bkaikki\/Wiktionary\b|\(CC BY-SA[^)]*\)/g;
27	
28	// Internal mphdict/ESUM labels are not learner-facing etymology prose.
29	const ESUM_LABEL_RE = /Стаття\s+ЕСУМ|етимонів\s*:/i;
30	
31	function collapseWhitespace(value: string): string {
32	  return value.replace(/\s+/g, " ").trim();
33	}
34	
35	function truncate(value: string, limit: number): string {
36	  if (value.length <= limit) return value;
37	  const breakpoint = value.lastIndexOf(" ", limit);
38	  const end = breakpoint > 0 ? breakpoint : limit;
39	  return `${value.slice(0, end)}…`;
40	}
41	
42	function sentenceCase(value: string): string {
43	  if (!value) return value;
44	  return value.charAt(0).toLocaleUpperCase("uk") + value.slice(1);
45	}
46	
47	function isEmptyOrPunctuation(value: string): boolean {
48	  return value.length === 0 || /^[\s\p{P}]+$/u.test(value);
49	}
50	
51	/**
52	 * Clean a raw Kaikki/Wiktionary etymology string so it reads as intentional
53	 * learner-facing prose. Returns `null` when the result would be garbage,
54	 * empty, or an internal source label rather than real etymology.
55	 */
56	export function cleanOriginText(value: string | undefined | null): string | null {
57	  if (!value) return null;
58	
59	  let text = collapseWhitespace(value);
60	  if (isEmptyOrPunctuation(text)) return null;
61	
62	  text = text
63	    .replace(LATIN_PARENTHETICAL_RE, "")
64	    .replace(COMPARE_CLAUSE_RE, "")
65	    .replace(SOURCE_FRAGMENT_RE, "")
66	    .replace(/\s+/g, " ")
67	    .trim();
68	
69	  // Pull stray punctuation back against the preceding word instead of deleting it.
70	  text = text.replace(/\s+([.,])/g, "$1").trim();
71	
72	  if (isEmptyOrPunctuation(text)) return null;
73	  if (ESUM_LABEL_RE.test(text)) return null;
74	
75	  text = sentenceCase(text);
76	  return truncate(text, MAX_LENGTH);
77	}
78	
79	/**
80	 * Return a short learner-facing source label.
81	 */
82	export function formatOriginSource(source: string | undefined | null): string {
83	  if (!source) return "";
84	  if (source === KAIKKI_SOURCE || source.includes("Wiktionary")) {
85	    return "Wiktionary";
86	  }
87	  return source;
88	}
89	
90	/**
91	 * Format an origin block for display. Fails closed: any unusable input
92	 * becomes `null` so callers can hide the surface instead of showing a raw dump.
93	 */
94	export function formatOrigin(
95	  input: OriginInput | undefined | null,
96	): FormattedOrigin | null {
97	  if (!input) return null;
98	  const text = cleanOriginText(input.text);
99	  if (!text) return null;
100	  const source = formatOriginSource(input.source);
101	  return { text, source };
102	}

