import { formatOrigin, cleanOriginText } from "../../src/lib/lexicon/format-origin";

const cases = [
  {
    input: { text: "From Latin monēta.", source: "kaikki/Wiktionary (CC BY-SA 3.0)" },
    expected: { text: "From Latin monēta.", source: "Wiktionary" },
  },
  {
    input: { text: "From наштовх(ну́ти) (naštovx(núty)) + -увати (-uvaty).", source: "kaikki/Wiktionary (CC BY-SA 3.0)" },
    expected: { text: "From наштовх(ну́ти) + -увати.", source: "Wiktionary" },
  },
  {
    input: { text: "Стаття ЕСУМ: монета; етимонів: 2.", source: "ЕСУМ" },
    expected: null,
  },
  {
    input: { text: "   ", source: "kaikki/Wiktionary (CC BY-SA 3.0)" },
    expected: null,
  },
];

let failed = 0;
for (const { input, expected } of cases) {
  const result = formatOrigin(input);
  const ok = JSON.stringify(result) === JSON.stringify(expected);
  if (!ok) {
    console.error("FAIL", input.text, "=>", result, "expected", expected);
    failed += 1;
  }
}
if (failed === 0) {
  console.log("format-origin smoke: ok");
} else {
  process.exit(1);
}

